45: function tone(freq,endFreq,duration,type='sine',volume=.045,delay=0){let a=audioReady();if(!a)return;try{let o=a.createOscillator(),g=a.createGain(),start=a.currentTime+delay;o.type=type;o.frequency.setValueAtTime(freq,start);o.frequency.exponentialRampToValueAtTime(Math.max(1,endFreq),start+duration);g.gain.setValueAtTime(.0001,start);g.gain.exponentialRampToValueAtTime(volume,start+.012);g.gain.exponentialRampToValueAtTime(.0001,start+duration);o.connect(g);g.connect(a.destination);o.start(start);o.stop(start+duration+.01)}catch(e){}}
46: function noise(duration=.16,volume=.035,frequency=900,type='lowpass'){let a=audioReady();if(!a)return;try{let n=Math.ceil(a.sampleRate*duration),buffer=a.createBuffer(1,n,a.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<n;i++)data[i]=Math.random()*2-1;let src=a.createBufferSource(),filter=a.createBiquadFilter(),g=a.createGain();src.buffer=buffer;filter.type=type;filter.frequency.value=frequency;g.gain.setValueAtTime(volume,a.currentTime);g.gain.exponentialRampToValueAtTime(.0001,a.currentTime+duration);src.connect(filter);filter.connect(g);g.connect(a.destination);src.start();src.stop(a.currentTime+duration)}catch(e){}}
